import optax
# Use verified RegCal implementation path
from storage.noema.submissions.dual_path_hybrid_motif_heads_regcal import build_network

BASE_SEED = 42
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        'hidden_dim': 256,
        'd_model': 256,
        'kernel_size': 7,
        'dropout_rate': 0.10,
        'motif_kernel_size': 5,
        'aggregator': 'mean_max',
        'regcal_l2': True,
        'head_dropout': 0.06,      # slightly stronger than 0.05
        'learning_rate': 0.001,
        'grad_clip': 1.0
    }

def create_network(hparams):
    return build_network(hparams.get('d_output', 1), hparams.get('task_type', 'regression'), hparams)

def create_optimizer(learning_rate: float = 0.001):
    # Global schedule: 200-step warmup to LR, cosine decay to 0.5*LR over 20k steps
    sched = optax.warmup_cosine_decay_schedule(
        init_value=0.0, peak_value=learning_rate,
        warmup_steps=200, decay_steps=20000, end_value=learning_rate * 0.5
    )
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=sched, weight_decay=0.01)
    )

def complete(params, opt_state, trial_data):
    ds, vm = trial_data.get('dataset'), trial_data.get('val_metric')
    print(f"[Complete] {ds} val_metric={vm}")
